/* FrostFlow UI: deliberately framework-free so it starts on a new Windows PC without a build step. */
const state = { view: 'dashboard', cart: [], products: [], customers: [], suppliers: [], loaded: false, revision: null, filters: {}, tables: {}, posSearch: '', pending: false, excel: { type: 'products', preview: null, filename: '', file: null, busy: false }, config: {} };
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = (value) => String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]);
const money = (paise = 0) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(paise) / 100);
const dateLabel = (value) => value ? new Intl.DateTimeFormat('en-IN', { dateStyle: 'medium' }).format(new Date(`${value}T00:00:00`)) : '—';
const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const available = (product) => Number(product.saleable_qty ?? product.stock_qty ?? 0);
const count = (value) => Number(value || 0).toLocaleString('en-IN');
const rupees = (value) => (Number(value || 0) / 100).toFixed(2);
const download = (type, title = 'Export Excel', template = false) => `<a class="button ghost" href="/api/excel/${template ? 'templates' : 'export'}/${esc(type)}.xlsx" download>${template ? '↓' : '⇩'} ${esc(title)}</a>`;
const metric = (label, value, note, color = 'blue') => `<article class="metric ${color}"><div class="metric-label">${esc(label)}</div><div class="metric-value">${value}</div><div class="metric-note">${esc(note)}</div></article>`;

async function api(path, options = {}) {
  const mutation = ['POST','PATCH','PUT','DELETE'].includes(options.method);
  const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json', ...(mutation ? { 'X-Idempotency-Key': $('#entry-form')?.dataset.requestKey || crypto.randomUUID() } : {}), ...(options.headers || {}) }, body: options.body ? JSON.stringify(options.body) : undefined });
  const data = await response.json().catch(() => ({}));
  if(response.status===404 && data.error==='API endpoint not found.') {const error=new Error('The running FrostFlow service does not support '+path.split('?')[0]+'. Save your work and reopen the FrostFlow ERP desktop shortcut to load the update. Refreshing alone is not enough.');error.status=404;throw error;}
  if (!response.ok) {const error=new Error(data.error || 'Something went wrong.');error.status=response.status;throw error;}
  return data;
}
function toast(message, type = 'success') {
  const node = document.createElement('div'); node.className = `toast ${type}`; node.textContent = message;
  $('#toast-root').append(node); setTimeout(() => node.remove(), 4200);
}
function badge(value) {
  const label = String(value || '').replaceAll('_', ' ');
  const klass = label.toLowerCase().replaceAll(' ', '_');
  return `<span class="badge ${klass}">${esc(label)}</span>`;
}
function setTitle(title, kicker) { $('#page-title').textContent = title; $('#section-kicker').textContent = kicker; }
function empty(title, copy = '') { return `<div class="empty"><div class="empty-icon">☃</div><b>${esc(title)}</b><div>${esc(copy)}</div></div>`; }
function options(items, selected, label = (item) => item.name, emptyLabel = 'Select…') { return `<option value="">${emptyLabel}</option>${items.map((item) => `<option value="${item.id}" ${Number(selected) === Number(item.id) ? 'selected' : ''}>${esc(label(item))}</option>`).join('')}`; }
function table(headers, rows, body) { return `<div class="card table-card"><div class="table-scroll"><table><thead><tr>${headers.map((head) => `<th scope="col">${head}</th>`).join('')}</tr></thead><tbody>${rows ? body : `<tr><td colspan="${headers.length}">${empty('Nothing to show yet')}</td></tr>`}</tbody></table></div></div>`; }
function dataTable(key, headers, rows, rowHTML, placeholder = 'Search these records…') {
  state.tables[key] = { headers, rows, rowHTML };
  const filter = state.filters[key] ||= { query: '', page: 0 };
  return `<section class="data-table" data-table="${key}"><div class="table-tools"><input class="search-input" aria-label="${esc(placeholder)}" data-table-search="${key}" value="${esc(filter.query)}" placeholder="${esc(placeholder)}"><span class="spacer"></span><span class="subtle">${count(rows.length)} records · 50 per page</span></div><div data-table-body="${key}">${tablePage(key)}</div></section>`;
}
function tablePage(key) {
  const { headers, rows, rowHTML } = state.tables[key]; const filter = state.filters[key];
  const query = filter.query.toLowerCase().trim(); const matches = query ? rows.filter((row) => Object.values(row).some((value) => String(value ?? '').toLowerCase().includes(query))) : rows;
  const pages = Math.max(1, Math.ceil(matches.length / 50)); filter.page = Math.min(filter.page, pages - 1);
  const selected = matches.slice(filter.page * 50, (filter.page + 1) * 50);
  return `${table(headers, selected.length, selected.map(rowHTML).join(''))}<div class="table-footer"><span>${count(matches.length)} matching records</span><div><button class="button ghost small" data-action="table-page" data-key="${key}" data-delta="-1" ${filter.page ? '' : 'disabled'}>Previous</button><span>Page ${filter.page + 1} of ${pages}</span><button class="button ghost small" data-action="table-page" data-key="${key}" data-delta="1" ${filter.page + 1 >= pages ? 'disabled' : ''}>Next</button></div></div>`;
}
function modal(title, subtitle, body, wide = false) {
  $('#modal-root').innerHTML = `<div class="modal-backdrop"><section class="modal ${wide ? 'wide' : ''}" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle || '')}</p></div><button class="close" data-action="close-modal" aria-label="Close">×</button></div>${body}</section></div>`;
}
function closeModal() { if ($('#entry-form button[type="submit"]:disabled')) return; $('#modal-root').innerHTML = ''; if (state.pending) { state.pending = false; render(); } }
function formModal(title, subtitle, fields, onSubmit, wide = false, submitText = 'Save') {
  modal(title, subtitle, `<form id="entry-form"><div class="modal-body"><div class="form-error" id="form-error" role="alert" hidden></div>${fields}</div><div class="modal-foot"><button class="button ghost" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">${esc(submitText)}</button></div></form>`, wide);
  $('#entry-form').addEventListener('submit', async (event) => {
    event.preventDefault(); const submit = $('button[type="submit"]', event.currentTarget); submit.disabled = true;
    event.currentTarget.dataset.requestKey ||= crypto.randomUUID();
    try { const result = await onSubmit(new FormData(event.currentTarget), event.currentTarget); submit.disabled = false; closeModal(); toast(typeof result === 'string' ? result : `${title} saved.`); await render(); }
    catch (error) { const box = $('#form-error'); if (box) { box.textContent = error.message; box.hidden = false; box.scrollIntoView({ block: 'nearest' }); } else toast(error.message, 'error'); submit.disabled = false; }
  });
  $('#entry-form').addEventListener('input', (event) => { event.currentTarget.dataset.requestKey = crypto.randomUUID(); });
  $('#entry-form').addEventListener('change', (event) => { event.currentTarget.dataset.requestKey = crypto.randomUUID(); });
  $('#entry-form input:not([type="hidden"]), #entry-form select')?.focus();
}
function heading(title, description, actions = '') { return `<div class="page-heading"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><div>${actions}</div></div>`; }
function productSelect(selected = '') { return options(state.products.filter((p) => p.active), selected, (p) => `${p.sku} — ${p.name} · ${available(p)} available`); }

async function ensureCatalogue() {
  if (!state.loaded) await refreshCatalogue();
}
async function refreshCatalogue() {
  const data = await api('/api/bootstrap'); state.products = data.products; state.customers = data.customers; state.suppliers = data.suppliers; state.revision = data.revision; state.loaded = true;
  for (const line of state.cart) { const product = state.products.find((p) => p.id === line.productId); line.stock = product?.active ? available(product) : 0; }
}

let amulDataset='invoice-view';
let amulOffset=0,amulQuery='';
async function renderAmul() {
  setTitle('Amul records', 'READ-ONLY · SEPARATE FROM LOCAL POS');
  const invoiceMode=amulDataset==='invoice-view';
  const requested=amulDataset+'?offset='+amulOffset+'&q='+encodeURIComponent(amulQuery);
  const data=await api(invoiceMode?'/api/amul/invoice-view?offset='+amulOffset+'&q='+encodeURIComponent(amulQuery):'/api/amul/'+requested);
  if(state.view!=='amul' || requested!==amulDataset+'?offset='+amulOffset+'&q='+encodeURIComponent(amulQuery))return;
  const s=data.status;
  const columns=Object.keys(data.rows[0] || {});
  $('#view').innerHTML=heading('Amul distribution', 'Synced copies only. Record Amul transactions in the Amul app; local POS and Excel imports affect local items only.')+
    `<div class="card card-body"><p>${s.running?'Syncing…':s.stale?'Cached data is stale or not yet available':'Cache is current'} · Last successful sync: ${esc(s.last_success?new Date(s.last_success).toLocaleString('en-IN'):'Never')}</p><p>${esc(s.error || '')}</p><p>${esc(s.scope || 'Sales and purchases from 5 Sep 2026')} · ${s.sync_mode==='incremental'?'Last run used latest changes only':'Next first run will build the local copy from the start date'}${s.source_checkpoint?' · Source checkpoint '+esc(s.source_checkpoint):''}</p><p>${s.enabled?'Manual Sync now fetches changes since the last successful source checkpoint; Full re-sync rebuilds from 2026-09-08. Background refresh every '+s.interval_seconds+' seconds.':'Sync is disabled. Use scripts/start-amul.ps1 to start with your SQL login.'}</p><p>Amul transactions are read-only; payment status edits are saved locally in FrostFlow.</p><label>Records <select id="amul-dataset"><option value="invoice-view" ${amulDataset==='invoice-view'?'selected':''}>invoice working view</option>${s.datasets.map(n=>`<option ${n===amulDataset?'selected':''} value="${esc(n)}">${esc(n.replaceAll('_',' '))}</option>`).join('')}</select></label> <button id="amul-refresh" class="button primary" ${!s.enabled||s.running?'disabled':''}>Sync now</button> <button id="amul-full-refresh" class="button ghost" ${!s.enabled||s.running?'disabled':''}>Full re-sync</button></div>`+
    `<form id="amul-search"><input aria-label="Search Amul records" name="query" value="${esc(amulQuery)}" placeholder="Search records"><button class="button ghost">Search</button></form>`+
    (invoiceMode ? amulInvoiceTable(data.rows) : table(columns.map(esc),data.rows.length,data.rows.map(row=>`<tr>${columns.map(c=>`<td>${esc(row[c])}</td>`).join('')}</tr>`).join('')))+
    `<div class="table-footer">${count(data.total)} matching records · Page ${Math.floor(amulOffset/50)+1}<button id="amul-prev" class="button ghost" ${amulOffset===0?'disabled':''}>Previous</button><button id="amul-next" class="button ghost" ${amulOffset+50>=data.total?'disabled':''}>Next</button></div>`;
  $('#amul-search').addEventListener('submit',e=>{e.preventDefault();amulQuery=new FormData(e.target).get('query');amulOffset=0;renderAmul().catch(error=>toast(error.message,'error'));});
  $('#amul-prev').addEventListener('click',()=>{amulOffset=Math.max(0,amulOffset-50);renderAmul().catch(error=>toast(error.message,'error'));});
  $('#amul-next').addEventListener('click',()=>{amulOffset+=50;renderAmul().catch(error=>toast(error.message,'error'));});
  $('#amul-dataset').addEventListener('change',async e=>{amulDataset=e.target.value;amulOffset=0;try{await renderAmul();}catch(error){toast(error.message,'error');}});
  $('#amul-refresh').addEventListener('click',async()=>{try{await api('/api/amul/sync',{method:'POST',body:{}});await renderAmul();}catch(error){toast(error.message,'error');}});
  $('#amul-full-refresh').addEventListener('click',async()=>{try{if(!confirm('Run full Amul re-sync from 2026-09-08? This keeps local edits but may take longer.'))return;await api('/api/amul/sync',{method:'POST',body:{full:true}});await renderAmul();}catch(error){toast(error.message,'error');}});
}
function amulInvoiceTable(rows) {
  return table(['Invoice', 'Retailer / route', 'Invoice / due date', 'Total', 'Paid', 'Outstanding', 'Status', 'Action'], rows.length, rows.map(r=>`<tr><td class="product-name">${esc(r.invoice_number)}<div class="subtle">Order ref: ${esc(r.order_ref)}</div></td><td>${esc(r.customer_name)}<div class="subtle">${esc(r.customer_code)} · ${esc(r.route_name || 'No route')}</div></td><td>${dateLabel(r.invoice_date)}<div class="subtle">Due: ${dateLabel(r.due_date)}</div></td><td>${money(r.total_paise)}</td><td>${money(r.paid_paise)}</td><td><strong>${money(r.outstanding_paise)}</strong></td><td>${badge(r.days_overdue>0 && r.payment_status!=='PAID'?'OVERDUE':r.payment_status)}</td><td><button class="button secondary small" data-action="amul-track" data-id="${esc(r.sal_id)}">Payment</button> <button class="button secondary small" data-action="amul-edit-items" data-id="${esc(r.sal_id)}">Edit items</button> <button class="button ghost small" data-action="amul-bill-details" data-id="${esc(r.sal_id)}">Bill / GST details</button> ${r.outstanding_paise>0 && r.payment_status!=='PAID'?`<button class="button secondary small" data-action="payment-reminder" data-source="AMUL" data-id="${esc(r.sal_id)}">Send payment reminder</button>`:''} <button class="button ghost small" data-action="amul-account" data-id="${esc(r.customer_id)}">Account</button> <button class="button danger small" data-action="amul-delete-invoice" data-id="${esc(r.sal_id)}">Delete</button></td></tr>`).join(''));
}
async function amulTrackingModal(salId) {
  const data=await api('/api/amul/invoices/'+encodeURIComponent(salId));
  const invoice={...data.invoice,outstanding_paise:Math.max(0,data.invoice.total_paise-data.invoice.paid_paise)};
  if(!invoice) throw new Error('Amul invoice not found.');
  formModal(`Amul ${invoice.invoice_number}`, `${invoice.customer_name} · Total ${money(invoice.total_paise)} · Outstanding ${money(invoice.outstanding_paise)}`, `<div class="form-grid"><div class="field"><label>Invoice number *</label><input name="invoiceNumber" required value="${esc(invoice.invoice_number)}"></div><div class="field"><label>Order reference</label><input name="orderRef" value="${esc(invoice.order_ref || '')}"></div><div class="field"><label>Retailer name *</label><input name="customerName" required value="${esc(invoice.customer_name)}"></div><div class="field"><label>Mobile</label><input name="mobile" value="${esc(invoice.mobile || '')}"></div><div class="field"><label>Payment status *</label><select name="paymentStatus" id="amul-payment-status"><option value="PENDING" ${invoice.payment_status==='PENDING'?'selected':''}>Pending</option><option value="PARTIAL" ${invoice.payment_status==='PARTIAL'?'selected':''}>Partially done</option><option value="PAID" ${invoice.payment_status==='PAID'?'selected':''}>Payment done</option></select></div><div class="field"><label>Paid amount (₹)</label><input name="paidAmount" id="amul-paid-amount" type="number" min="0" step=".01" value="${rupees(invoice.paid_paise)}"></div><div class="field"><label>Payment date</label><input name="paymentDate" type="date" value="${esc(invoice.payment_date || today())}"></div><div class="field full"><label>Notes</label><textarea name="notes" placeholder="Cash, UPI ref, follow-up note…">${esc(invoice.notes || '')}</textarea></div></div>`, async f=>{await api(`/api/amul/invoices/${encodeURIComponent(salId)}/tracking`,{method:'PATCH',body:Object.fromEntries(f)});}, false, 'Save invoice');
}
async function amulRetailerModal(retailerId) {
  const retailer=await api('/api/amul-local/retailers/'+encodeURIComponent(retailerId));
  if(!retailer) throw new Error('Retailer not found.');
  formModal(`Edit ${retailer.retailer_name}`, 'Changes are saved only in FrostFlow local copy.', `<div class="form-grid"><div class="field full"><label>Retailer name *</label><input name="name" required value="${esc(retailer.retailer_name)}"></div><div class="field"><label>Mobile</label><input name="mobile" value="${esc(retailer.mobile || '')}"></div><div class="field"><label>GST / tax no.</label><input name="gstin" value="${esc(retailer.gstin || '')}"></div><div class="field"><label>Credit days</label><input name="creditDays" type="number" min="0" step="1" value="${esc(retailer.credit_days || 0)}"></div><div class="field"><label>Credit limit (₹)</label><input name="creditLimit" type="number" min="0" step=".01" value="${rupees(retailer.credit_limit_paise || 0)}"></div><div class="field full"><label>Address</label><textarea name="address">${esc(retailer.address || '')}</textarea></div></div>`, async f=>{await api(`/api/amul/retailers/${encodeURIComponent(retailerId)}`,{method:'PATCH',body:Object.fromEntries(f)});}, false, 'Save retailer');
}
async function amulPosSaleModal(productId) {
  const product=await api('/api/amul-local/products/'+encodeURIComponent(productId));
  if(!product) throw new Error('Amul product not found.');
  const price=product.mrp_paise || product.selling_price_paise || 0;
  formModal(`Sell ${product.product_name}`, `Deducts only from FrostFlow local Amul stock. Amul SQL remains read-only. Available stock: ${count(product.stock_qty)}`, `<div class="form-grid"><div class="field"><label>Quantity *</label><input name="quantity" type="number" min="1" max="${esc(product.stock_qty)}" step="1" value="1" required></div><div class="field"><label>Retail price / MRP (₹) *</label><input name="unitPrice" type="number" min="0.01" step=".01" value="${rupees(price)}" required></div><div class="field"><label>Payment method</label><select name="method"><option>CASH</option><option>UPI</option><option>CARD</option><option>BANK</option><option>OTHER</option></select></div><div class="field"><label>Sale date</label><input name="saleDate" type="date" value="${today()}"></div><div class="field full"><label>MRP total</label><strong id="amul-mrp-total">${money(price)}</strong><span class="hint">Quantity × retail price. No additional tax is added.</span></div><div class="field full"><label>Notes</label><textarea name="notes" placeholder="Counter sale note, UPI ref, customer name…"></textarea></div></div>`, async f=>{const body=Object.fromEntries(f);body.productId=product.product_id;const sale=await api('/api/amul/pos-sales',{method:'POST',body});return `Amul POS sale ${sale.sale_number} saved and stock reduced locally.`;}, false, 'Complete Amul sale');
  const totalNode=$('#amul-mrp-total'); const form=totalNode.closest('form');
  const updateTotal=()=>{const qty=Number($('[name=quantity]',form).value);const amount=Math.round(Number($('[name=unitPrice]',form).value)*100);totalNode.textContent=money(Number.isFinite(qty*amount)?qty*amount:0);};
  $('[name=quantity]',form).addEventListener('input',updateTotal);
  $('[name=unitPrice]',form).addEventListener('input',updateTotal);
}
async function amulInvoiceItems(id) {
  const detail=await api('/api/amul/invoices/'+encodeURIComponent(id));
  const renderLine=(l={})=>`<div class="line-editor invoice-edit-row"><div class="field"><label>Product / batch</label><select name="batch">${detail.batches.map(b=>`<option value="${esc(JSON.stringify([b.product_id,b.batch_id]))}" ${b.product_id===l.product_id && b.batch_id===l.batch_id?'selected':''}>${esc(b.product_name)} · ${esc(b.batch_code)} · ${count(b.stock_qty)} stock</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="1" step="1" required value="${l.quantity || 1}"></div><div class="field"><label>Free quantity</label><input name="freeQuantity" type="number" min="0" step="1" required value="${l.free_quantity || 0}"></div><div class="field"><label>Unit price before tax (₹)</label><input name="unitPrice" type="number" min="0" step=".01" required value="${rupees(l.unit_rate_paise || 0)}"></div><div class="field"><label>Total line tax (₹)</label><input name="taxAmount" type="number" min="0" step=".01" required value="${rupees(l.tax_paise || 0)}"></div><div class="field"><label>Line discount (−) / charges (+), ₹</label><input name="adjustment" type="number" step=".01" value="${rupees((l.net_paise ?? 0)-(l.quantity || 0)*(l.unit_rate_paise || 0)-(l.tax_paise || 0))}"></div><button type="button" class="button danger small remove-invoice-row">Remove</button></div>`;
  formModal('Items — '+detail.invoice.invoice_number,'Local correction: total = quantity × price + line tax. Stock and receivable update together. Review tax and discounts before saving.',`<div id="invoice-edit-lines">${detail.items.map(renderLine).join('')}</div><button type="button" id="add-invoice-row" class="button secondary">＋ Add item</button><div class="field"><label>Reason for correction *</label><input name="reason" required></div>`,async(f,form)=>{
    const items=$$('.invoice-edit-row',form).map(row=>{const [productId,batchId]=JSON.parse($('[name=batch]',row).value);return {productId,batchId,quantity:$('[name=quantity]',row).value,freeQuantity:$('[name=freeQuantity]',row).value,unitPrice:$('[name=unitPrice]',row).value,taxAmount:$('[name=taxAmount]',row).value,adjustment:$('[name=adjustment]',row).value};});
    await api('/api/amul/invoices/'+encodeURIComponent(id),{method:'PATCH',body:{items,reason:f.get('reason')}});
  },true,'Save correction');
  $('#add-invoice-row').onclick=()=>$('#invoice-edit-lines').insertAdjacentHTML('beforeend',renderLine());
  $('#invoice-edit-lines').onclick=e=>{if(e.target.closest('.remove-invoice-row'))e.target.closest('.invoice-edit-row').remove();};
}
async function amulBillDetails(id) {
  const d=await api('/api/amul/invoices/'+encodeURIComponent(id)+'/bill');
  const rate=value=>new Intl.NumberFormat('en-IN',{minimumFractionDigits:2,maximumFractionDigits:6}).format(value);
  modal('Original retailer bill — '+d.invoice.invoice_number,'Recorded rates and amounts from the old Amul bill. POS uses MRP separately.',`<div class="modal-body"><p><strong>${esc(d.invoice.customer_name)}</strong> · ${dateLabel(d.invoice.invoice_date)} · Order ref ${esc(d.invoice.order_ref)} · GSTIN ${esc(d.source_gstin || 'Not available')}</p><div class="notice">GST amounts below are recorded bill tax. The percentage shown is calculated from those amounts, not a verified GST slab. CGST / SGST / IGST components are not present in the current cache.</div>${table(['Product / batch','Qty / free','MRP','Retailer unit rate ₹','Gross','Discount / adjustment','Taxable¹','GST %²','GST amount','Line total','Purchase reference'],d.items.length,d.items.map(l=>`<tr><td>${esc(l.product_name || l.product_id)}<div class="subtle">Batch ${esc(l.batch_id)}</div></td><td>${count(l.quantity)} / ${count(l.free_quantity)}</td><td>${money(l.unit_mrp_paise)}</td><td>${rate(l.unit_rate_rupees)}</td><td>${money(l.gross_paise)}</td><td>${money(l.discount_or_adjustment_paise)}</td><td>${money(l.taxable_paise)}</td><td>${l.effective_tax_percent==null?'—':rate(l.effective_tax_percent)+'%'}</td><td>${money(l.tax_paise)}</td><td>${money(l.net_paise)}</td><td>${l.purchase_reference?`${esc(l.purchase_reference.bill_number)}<div class="subtle">Recorded unit cost ${money(l.purchase_reference.unit_cost_paise)} · line tax ${money(l.purchase_reference.tax_paise)}</div>`:'Purchase cost not synced'}</td></tr>`).join(''))}<p class="hint">¹ Line total less recorded tax. ² Effective percentage, rounded to two decimals. Discount / adjustment is the difference between gross and taxable amount; it can include schemes or rounding.</p><p>Recorded bill GST: <strong>${money(d.source_tax_paise)}</strong> · Header adjustment: <strong>${money(d.header_adjustment_paise)}</strong> · Original bill total: <strong>${money(d.source_total_paise)}</strong></p>${d.locally_corrected?`<div class="notice">This bill has local corrections. Current local total: ${money(d.invoice.total_paise)}. Original amounts above remain preserved.</div>`:''}</div><div class="modal-foot"><button class="button primary" data-action="close-modal">Close</button></div>`,true);
}
async function amulStockModal(productId,batchId,locationId) {
  const row=await api('/api/amul/inventory?'+new URLSearchParams({productId,batchId,locationId:locationId || ''}));
  if(!row) throw new Error('Amul stock row not found.');
  formModal(`Edit stock — ${row.product_name}`, `Local correction only. Amul SQL is not changed. Batch ${row.batch_code || row.batch_id} · Location ${row.location_id || '—'}`, `<div class="form-grid"><div class="field"><label>Current local stock</label><input value="${esc(row.stock_qty)}" disabled></div><div class="field"><label>New stock *</label><input name="stockQty" type="number" min="0" step="1" value="${esc(row.stock_qty)}" required></div><div class="field full"><label>Reason</label><textarea name="reason" placeholder="Manual count, freezer issue, mismatch correction…"></textarea></div></div>`, async f=>{const body=Object.fromEntries(f);body.productId=productId;body.batchId=batchId;body.locationId=locationId;await api('/api/amul/inventory',{method:'PATCH',body});return 'Amul local stock updated.';}, false, 'Save stock');
}
