function cartTotals() {
  return state.cart.reduce((totals, item) => { const gross = item.quantity * item.unitPrice; const taxable = Math.round(gross * 10000 / (10000 + item.gstBps)); const tax = gross - taxable; totals.subtotal += taxable; totals.tax += tax; return totals; }, { subtotal: 0, tax: 0, total: 0 });
}
function addCart(productId) {
  const priced=state.products.find(p=>p.id===Number(productId));
  if(priced && !(priced.mrp_paise>0)) {productForm(priced.id);return toast('Set the product MRP before adding it to POS.','error');}
  const product = state.products.find((p) => p.id === Number(productId)); if (!product?.active || available(product) < 1) return toast('This product has no saleable stock.', 'error');
  const existing = state.cart.find((item) => item.productId === product.id);
  if (existing) { if (existing.quantity >= available(product)) return toast('Only the currently available stock can be added.', 'error'); existing.quantity++; }
  else state.cart.push({ productId: product.id, name: product.name, sku: product.sku, quantity: 1, unitPrice: product.mrp_paise, gstBps: product.gst_bps, stock: available(product) });
  renderPOS();
}
function changeCart(productId, delta) { const item = state.cart.find((line) => line.productId === Number(productId)); if (!item) return; if (delta > 0 && item.quantity >= item.stock) return toast('No more currently available stock.', 'error'); item.quantity += delta; if (item.quantity <= 0) state.cart = state.cart.filter((line) => line !== item); renderPOS(); }

async function renderPOS() {
  setTitle('Retail POS', 'FAST COUNTER BILLING'); await ensureCatalogue(); const totals = cartTotals(); totals.total = totals.subtotal + totals.tax;
  state.posCatalogue=await api('/api/pos/catalogue'); const amul={rows:state.posCatalogue.filter(p=>p.source==='AMUL').map(p=>({product_id:p.id,product_name:p.name,sku:p.code,barcode:p.barcode,stock_qty:p.stock,mrp_paise:p.mrp,selling_price_paise:p.price,active:p.active}))};state.amulPosCatalogue=amul.rows;
  $('#view').innerHTML = `<section class="pos-layout"><div class="pos-left"><div class="pos-toolbar"><input id="pos-search" class="search-input" placeholder="Search product, SKU or barcode"><button class="button ghost" data-action="open-product">＋ Product</button><button class="button ghost" data-action="amul-sync-now">Sync Amul</button><button class="button ghost" data-action="refresh-catalogue">↻</button></div><button class="button secondary" data-view="itemSheet">Edit items as sheet</button><div id="pos-pages" class="pos-toolbar"></div><h3 class="section-title">Local POS items</h3><div id="pos-grid" class="pos-grid">${posTiles(state.products)}</div><h3 class="section-title">Amul synced items</h3><div id="amul-pos-grid" class="pos-grid">${amulPosTiles(amul.rows)}</div></div><aside class="pos-cart"><div class="pos-cart-head"><div><h2>Current sale</h2><span class="subtle">${state.cart.length} product line${state.cart.length === 1 ? '' : 's'}</span></div><button class="button ghost small" data-action="clear-cart">Clear</button></div><div class="cart-items">${state.cart.length ? state.cart.map((item) => `<div class="cart-row"><div><strong>${esc(item.name)}</strong><div class="subtle">${money(item.unitPrice)} MRP · GST included</div><div class="cart-qty"><button data-action="cart-change" data-id="${item.productId}" data-delta="-1">−</button><input value="${item.quantity}" readonly><button data-action="cart-change" data-id="${item.productId}" data-delta="1">+</button></div></div><div><strong>${money(item.quantity * item.unitPrice)}</strong><button class="button danger small" data-action="cart-remove" data-id="${item.productId}">Remove</button></div></div>`).join('') : empty('Cart is empty', 'Select a local product to begin billing.')}</div><div class="cart-total"><div class="total-line"><span>Taxable value</span><span>${money(totals.subtotal)}</span></div><div class="total-line"><span>Included GST</span><span>${money(totals.tax)}</span></div><div class="total-line grand"><span>Grand total</span><span>${money(totals.total)}</span></div><button class="button primary checkout" data-action="checkout" ${state.cart.length ? '' : 'disabled'}>Complete sale →</button></div></aside></section>`;
  $('#pos-search').value = state.posSearch;
  filterPOS();
  $('#pos-search')?.addEventListener('input', (event) => { state.posSearch = event.target.value; state.posPage=0; filterPOS(); });
  $('#pos-search')?.addEventListener('keydown', (event) => { if (event.key !== 'Enter') return; event.preventDefault(); const query = state.posSearch.trim().toLowerCase(); const exact = state.products.find((p) => p.active && [p.barcode, p.sku].some((value) => value && value.toLowerCase() === query)); if (!exact) return toast('No exact SKU or barcode match. Select a product below.', 'error'); addCart(exact.id); state.posSearch = ''; $('#pos-search').value = ''; filterPOS(); $('#pos-search').focus(); });
}
function filterPOS() {
 const q=state.posSearch.toLowerCase().trim();
 const local=state.products.filter(p=>productKeywordMatch(p.name+' '+p.sku+' '+(p.barcode||''),q));
 const amul=(state.amulPosCatalogue || []).filter(p=>productKeywordMatch(p.product_name+' '+p.sku+' '+(p.barcode||''),q));
 const pages=Math.max(1,Math.ceil(Math.max(local.length,amul.length)/60));state.posPage=Math.min(state.posPage||0,pages-1);
 const start=state.posPage*60;
 if($('#pos-grid'))$('#pos-grid').innerHTML=posTiles(local.slice(start,start+60));
 if($('#amul-pos-grid'))$('#amul-pos-grid').innerHTML=amulPosTiles(amul.slice(start,start+60));
 if($('#pos-pages')) {$('#pos-pages').innerHTML=`<button class="button ghost" id="pos-prev" ${state.posPage===0?'disabled':''}>Previous</button><span>Page ${state.posPage+1} / ${pages} · ${local.length} local + ${amul.length} Amul products</span><button class="button ghost" id="pos-next" ${state.posPage+1>=pages?'disabled':''}>Next</button>`;$('#pos-prev').onclick=()=>{state.posPage--;filterPOS();};$('#pos-next').onclick=()=>{state.posPage++;filterPOS();};}
}
function posTiles(products) { const rows = products; return rows.length ? rows.slice(0, 120).map((p) => `<button class="product-tile" data-action="${p.mrp_paise>0?'add-cart':'edit-product'}" data-id="${p.id}" ${!p.active || (available(p) <= 0 && p.mrp_paise>0) ? 'disabled' : ''}><div class="tile-cat">${esc(p.category)}</div><strong>${esc(p.name)}</strong><div class="subtle">${esc(p.sku)}</div><div class="tile-bottom"><span class="tile-price">${p.mrp_paise>0?money(p.mrp_paise):'Set MRP'}<small>MRP · GST included</small></span><span class="stock-count">${available(p)} ${esc(p.unit)}</span></div></button>`).join('') + (rows.length > 120 ? '<div class="hint">Showing 120 products. Search or scan to narrow the catalogue.</div>' : '') : empty('No matching product', 'Search by product name, SKU or barcode.'); }
function amulPosTiles(products) {
  const query = state.posSearch.toLowerCase().trim();
  const rows = products.filter((p) => productKeywordMatch(`${p.product_name} ${p.sku} ${p.barcode || ''}`,query));
  return rows.length ? rows.slice(0,120).map((p)=>`<button class="product-tile" data-action="amul-pos-sale" data-id="${esc(p.product_id)}" ${!p.active || Number(p.stock_qty || 0) <= 0 ? 'disabled' : ''}><div class="tile-cat">Amul local stock</div><strong>${esc(p.product_name)}</strong><div class="subtle">${esc(p.sku || p.code)}</div><div class="tile-bottom"><span class="tile-price">${money(p.mrp_paise || p.selling_price_paise)}<small>MRP ${money(p.mrp_paise)}</small></span><span class="stock-count">${count(p.stock_qty)} stock</span></div></button>`).join('') + (rows.length>120?'<div class="hint">Showing 120 Amul products. Search to narrow.</div>':'') : empty('No matching Amul product', 'Synced Amul items appear here after sync.');
}

