function excelPreviewHTML() {
  const p = state.excel.preview; if (!p) return '';
  const errors = p.errors || []; const warnings = p.warnings || [];
  const totals = p.totals || {};
  return `<div class="preview-status ${p.valid ? 'valid' : 'invalid'}"><div><h3>${p.valid ? 'Preview passed — ready for your review' : 'Import has errors — nothing has been changed'}</h3><p>${count(p.rowCount)} rows · ${errors.length} errors · ${warnings.length} warnings${p.expiresAt ? ' · preview expires ' + esc(new Date(p.expiresAt).toLocaleTimeString('en-IN')) : ''}</p></div>${badge(p.valid ? 'VALIDATED' : 'NEEDS CORRECTION')}</div>${p.valid && totals.stockUnitsBefore !== undefined ? `<section class="metric-grid three">${metric('Physical stock after import', count(totals.stockUnitsAfter), `${count(totals.stockUnitsBefore)} before · ${Number(totals.stockUnitChange) >= 0 ? '+' : ''}${count(totals.stockUnitChange)} units`, 'blue')}${metric('Cost value after import', money(totals.stockValueAfterPaise), `Before: ${money(totals.stockValueBeforePaise)}`, 'teal')}${metric('Change in cost value', money(totals.stockValueChangePaise), 'Preview only · no records changed', 'orange')}</section>` : ''}${errors.length ? dataTable('import-errors', ['Excel row', 'Field', 'Error'], errors, (r) => `<tr><td>${esc(r.row || 'File')}</td><td>${esc(r.field || '—')}</td><td class="wrap-cell">${esc(r.message || r)}</td></tr>`) : ''}${warnings.length ? `<div class="notice warning">${warnings.map((w) => `<p>${esc(typeof w === 'string' ? w : w.message || JSON.stringify(w))}</p>`).join('')}</div>` : ''}${dataTable('import-preview', ['Excel row', 'Action', 'Preview'], p.rows || [], (r) => `<tr><td>${esc(r.row)}</td><td>${badge(r.action)}</td><td class="wrap-cell">${esc(typeof r.summary === 'string' ? r.summary : JSON.stringify(r.summary))}</td></tr>`, 'Search preview rows…')}${p.valid ? `<div class="commit-panel"><label class="check-label"><input id="confirm-import" type="checkbox"> I reviewed this preview and want to post ${count(p.rowCount)} rows.</label><button class="button primary" data-action="excel-commit" disabled>3. Post validated import</button><p class="hint">All rows post together. If any row fails, the entire import rolls back. Re-upload an edited file to create a new preview.</p></div>` : '<div class="notice">Correct the errors in Excel and choose the updated file, then validate again.</div>'}`;
}
async function previewExcel() {
  const ex = state.excel; if (!ex.file || ex.busy) return; ex.busy = true; ex.preview = null;
  await renderExcel();
  try {
    const base64 = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = () => reject(new Error('The selected file could not be read.')); reader.readAsDataURL(ex.file); });
    ex.preview = await api('/api/excel/preview', { method: 'POST', body: { type: ex.type, filename: ex.filename, base64 } }); ex.commitKey = crypto.randomUUID();
  } catch (error) { toast(error.message, 'error'); }
  finally { ex.busy = false; if (state.view === 'excel') { await renderExcel(); $('#excel-preview')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }
}
async function commitExcel(button) {
  const ex = state.excel; if (!ex.preview?.valid || ex.busy || !$('#confirm-import')?.checked) return;
  ex.busy = true; button.disabled = true; button.textContent = 'Posting import…';
  try {
    const result = await api('/api/excel/commit', { method: 'POST', headers: { 'X-Idempotency-Key': ex.commitKey }, body: { token: ex.preview.token } });
    toast(`Import posted: ${count(result.rowCount ?? ex.preview.rowCount)} rows. Stock and accounts are refreshed.`);
    ex.preview = null; ex.file = null; ex.filename = ''; await refreshCatalogue();
  } catch (error) { toast(error.message, 'error'); }
  finally { ex.busy = false; if (state.view === 'excel') await renderExcel(); }
}
