function whatsappLink(phone,name) {
  let digits=String(phone || '').replace(/\D/g,'');
  if(digits.length===10) digits='91'+digits;
  if(!/^[1-9]\d{10,14}$/.test(digits)) return '';
  return `<a class="button ghost small" href="https://wa.me/${digits}?text=${encodeURIComponent('Hello '+name+', ')}" target="_blank" rel="noopener noreferrer">WhatsApp</a>`;
}
