async function render() {
  if (state.rendering) { state.renderAgain = true; return; } state.rendering = true;
  try {
    $$('.nav-item').forEach((node) => node.classList.toggle('active', node.dataset.view === state.view));
    const views = { wholesale: renderWholesale, itemSheet: renderItemSheet, routes: renderRoutes, amul: renderAmul, dashboard: renderDashboard, pos: renderCounter, products: renderProducts, inventory: renderInventory, customers: () => renderParties('CUSTOMER'), suppliers: () => renderParties('SUPPLIER'), orders: renderOrders, invoices: renderInvoices, purchases: renderPurchases, payments: renderPayments, receivables: renderReceivables, excel: renderExcel, expenses: renderExpenses, returns: renderReturns, reports: renderReports, audit: renderAudit, settings: renderSettings };
    await views[state.view]();
    if(state.view!=='amul')$('#view').insertAdjacentHTML('afterbegin','<p class="hint">Local business records only — Amul stock and transactions are separate under Amul · read-only. Do not re-import Amul stock into the local POS.</p>');
  } catch (error) { $('#view').innerHTML = `<div class="card"><div class="card-body">${empty('Could not load this area', error.message)}</div></div>`; }
  finally { state.rendering = false; if (state.renderAgain) { state.renderAgain = false; render(); } }
}

